BEGIN TRANSACTION;
CREATE TABLE x_exact_commands(id TEXT PRIMARY KEY,command TEXT NOT NULL,release_receipt TEXT NOT NULL,state TEXT NOT NULL,attempt_batch TEXT,accept_clock TEXT NOT NULL,release_evidence TEXT NOT NULL,execute_evidence TEXT) STRICT;
CREATE TABLE x_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE x_sim_batches(id TEXT PRIMARY KEY,request TEXT NOT NULL,result TEXT NOT NULL) STRICT;
CREATE TABLE x_sim_busts(id TEXT PRIMARY KEY,exec_id TEXT NOT NULL,quantity INTEGER NOT NULL) STRICT;
CREATE TABLE x_sim_meta(k TEXT PRIMARY KEY,v TEXT NOT NULL) STRICT;
CREATE TABLE x_sim_originals(id TEXT PRIMARY KEY,raw TEXT NOT NULL) STRICT;
COMMIT;
